
pub const UNICODE_VERSION: &str = crate::UNICODE_VERSION;

#[derive(Debug, Clone, Copy)]
pub struct DecompEntry {
    pub cp: u32,
    pub mapping: u16,
}

pub const POSITIONAL_COUNT: usize = 2357;
pub const ORTHOGRAPHIC_COUNT: usize = 2081;
pub const LEGACY_COUNT: usize = 725;
pub const CURSIVE_COUNT: usize = 731;
pub const RESIDUAL_COUNT: usize = 20;
pub const EXPLICIT_DECOMPOSITION_COUNT: usize = 5914;
pub const UNIQUE_MAPPING_COUNT: usize = 3850;

pub fn lookup_positional(cp: u32) -> Option<&'static [u32]> {
    lookup(cp, POSITIONAL)
}
pub fn lookup_orthographic(cp: u32) -> Option<&'static [u32]> {
    lookup(cp, ORTHOGRAPHIC)
}
pub fn lookup_legacy(cp: u32) -> Option<&'static [u32]> {
    lookup(cp, LEGACY)
}
pub fn lookup_cursive(cp: u32) -> Option<&'static [u32]> {
    lookup(cp, CURSIVE)
}
pub fn lookup_residual(cp: u32) -> Option<&'static [u32]> {
    lookup(cp, RESIDUAL)
}

pub fn explicit_decompositions() -> impl Iterator<Item = (u32, &'static [u32])> {
    POSITIONAL
        .iter()
        .chain(ORTHOGRAPHIC)
        .chain(LEGACY)
        .chain(CURSIVE)
        .chain(RESIDUAL)
        .map(|entry| (entry.cp, mapping(entry.mapping)))
}

fn lookup(cp: u32, table: &[DecompEntry]) -> Option<&'static [u32]> {
    table
        .binary_search_by_key(&cp, |entry| entry.cp)
        .ok()
        .map(|idx| mapping(table[idx].mapping))
}

