#[cfg(test)]
mod tests {
    use super::*;

    fn assert_decomp_table_sorted_and_bounded(name: &str, table: &[DecompEntry]) {
        let mut previous_cp = None;
        for (index, entry) in table.iter().enumerate() {
            assert!(
                entry.cp <= 0x10FFFF,
                "{name}[{index}] exceeds Unicode scalar range"
            );
            assert!(
                usize::from(entry.mapping) < UNIQUE_MAPPING_COUNT,
                "{name}[{index}] points outside mapping table"
            );
            if let Some(prev) = previous_cp {
                assert!(prev < entry.cp, "{name}[{index}] is unsorted");
            }
            previous_cp = Some(entry.cp);
        }
    }

    #[test]
    fn generated_counts_match_unicodedata() {
        assert_eq!(UNICODE_VERSION, crate::UNICODE_VERSION);
        assert_eq!(POSITIONAL_COUNT, 2357);
        assert_eq!(ORTHOGRAPHIC_COUNT, 2081);
        assert_eq!(LEGACY_COUNT, 725);
        assert_eq!(CURSIVE_COUNT, 731);
        assert_eq!(RESIDUAL_COUNT, 20);
        assert_eq!(EXPLICIT_DECOMPOSITION_COUNT, 5914);
        assert_eq!(UNIQUE_MAPPING_COUNT, 3850);
        assert_eq!(lookup_orthographic(0x00C0), Some(&[0x0041, 0x0300][..]));
        assert_eq!(lookup_positional(0xFF21), Some(&[0x0041][..]));
        assert_eq!(lookup_cursive(0xFE91), Some(&[0x0628][..]));
    }

    #[test]
    fn decomposition_binary_search_tables_are_sorted_and_mapping_bounded() {
        assert_decomp_table_sorted_and_bounded("POSITIONAL", POSITIONAL);
        assert_decomp_table_sorted_and_bounded("ORTHOGRAPHIC", ORTHOGRAPHIC);
        assert_decomp_table_sorted_and_bounded("LEGACY", LEGACY);
        assert_decomp_table_sorted_and_bounded("CURSIVE", CURSIVE);
        assert_decomp_table_sorted_and_bounded("RESIDUAL", RESIDUAL);
    }
}
